using Fugue.Application.Features.Webhooks.Queries;
using Microsoft.AspNetCore.Mvc;

namespace Fugue.Api.Contracts;

/// <summary>Body of POST /webhooks/subscriptions. The secret is generated by the server.</summary>
public sealed record CreateWebhookSubscriptionRequest(string Name, string Url, string[] EventTypes);

/// <summary>Body of PUT /webhooks/subscriptions/{id}. Requires If-Match. The secret is changed only by rotating it.</summary>
public sealed record UpdateWebhookSubscriptionRequest(string Name, string Url, string[] EventTypes, bool IsActive);

/// <summary>Body of PUT /dev/webhook-sink/secret: the signing secret the Development sink should trust.</summary>
public sealed record SetSinkSecretRequest(string Secret);

/// <summary>Query parameters of the webhook deliveries list, bound as one object.</summary>
public sealed record WebhookDeliveryListFilter
{
    [FromQuery(Name = "status")]
    public string? Status { get; init; }

    [FromQuery(Name = "subscriptionId")]
    public Guid? SubscriptionId { get; init; }

    [FromQuery(Name = "eventType")]
    public string? EventType { get; init; }

    [FromQuery(Name = "limit")]
    public int? Limit { get; init; }

    [FromQuery(Name = "cursor")]
    public string? Cursor { get; init; }

    public ListWebhookDeliveriesQuery ToQuery() => new(Status, SubscriptionId, EventType, Limit, Cursor);
}
